 return `<main class="studio-content"><header><div><span class="eyebrow author">Обзор</span><h1>Что происходит вокруг <em>ваших работ</em>.</h1></div><button class="btn author" data-studio="profile">Мой профиль</button></header><section class="studio-metrics">${metric('В предпочтениях',fmt(getAuthorProfile('Дени Вильнёв').preferred),'+1 284 за 30 дней')}${metric('Рецензий','3 842','+218 за 30 дней')}${metric('Авторских лайков','612','поставлено зрителям')}${metric('Средняя оценка','89','по вашим работам')}</section><section class="studio-block"><div class="studio-head"><h2>Дюна: Часть вторая</h2><button class="quiet" data-studio="works">Все работы →</button></div><div class="focus"><img src="${m.poster}"><div><div class="film-metrics">${metric('Рецензий','1 284','+84 за неделю')}${metric('Оценок','18 420','+962 за неделю')}${metric('В предпочтениях',fmt(m.preferred),'+471 за неделю')}</div><div class="studio-score-detail">${scoreTriplet(m,true,true)}</div></div></div></section><section class="studio-block"><div class="studio-head"><h2>Последние мнения</h2><button class="quiet" data-studio="audience">Смотреть все →</button></div><div class="studio-audience">${REVIEWS.slice(0,3).map(r=>studioReviewCard(r)).join('')}</div></section></main>`
